declare const tools: { exec_command(args: {
  // Shell command to execute.
  cmd: string;
  // User-facing approval question for `require_escalated`; omit otherwise.
  justification?: string;
  // True runs the shell with -l/-i semantics; false disables them. Defaults to true.
  login?: boolean;
  // Output token budget. Defaults to 10000 tokens; larger requests may be capped by policy.
  max_output_tokens?: number;
  // Reusable approval prefix for `cmd`, only with `sandbox_permissions: "require_escalated"`; for example ["git", "pull"].
  prefix_rule?: Array<string>;
  // Per-command sandbox override. Defaults to `use_default`; use `require_escalated` for unsandboxed execution.
  sandbox_permissions?: "use_default" | "require_escalated";
  // Shell binary to launch. Defaults to the user's default shell.
  shell?: string;
  // True allocates a PTY for the command; false or omitted uses plain pipes.
  tty?: boolean;
  // Working directory for the command. Defaults to the turn cwd.
  workdir?: string;
  // Wait before yielding output. Defaults to 10000 ms; effective range is 250-30000 ms.
  yield_time_ms?: number;
}): Promise<{
  // Chunk identifier included when the response reports one.
  chunk_id?: string;
  // Process exit code when the command finished during this call.
  exit_code?: number;
  // Approximate token count before output truncation.
  original_token_count?: number;
  // Command output text, possibly truncated.
  output: string;
  // Session identifier to pass to write_stdin when the process is still running.
  session_id?: number;
  // Elapsed wall time spent waiting for output in seconds.
  wall_time_seconds: number;
}>; };
```"},{"name":"mcp__swarm__post","description":"Post a message with a title (a one-line summary) to a channel; every post gets a number. Share what you are exploring, building, or have found (e.g. how the original program behaves in some case, a test command, an edge case, a working module), propose how to split up work, or ask others something; mention someone with @name. The text is limited to 20000 characters. Share code by pointing at a commit: commit it first (`git commit`; the platform commits nothing, and changes you have not committed are not shared), in an earlier message: the tool calls of one message run at once, so a post beside the `git commit` may point at the HEAD from before it. `attach` names files of a commit, each optionally with lines (e.g. `src/main.py#L10-40` in your HEAD, or `<sha>:src/main.py#L10-40`), or a whole commit (`HEAD` or a sha), or one file of your workspace as it is now, committed or not (`file:src/main.py`, optionally with lines; only that file is opened, without history); the platform adds a pointer `[[<sha>:<path>#L<start>-<end>]]` for each to the text. You can also write pointers into the text yourself, to a commit of your repository or one shared with you (`[[<sha>]]` for a whole commit, or with a path and lines); a post holds at most 10 pointers (attach items and pointers in the text, each counted as written). A pointer opens that commit, read-only, to everyone who can read the post (your group), without the history of your commits; they see the code against their own files and can get it into their repository with `git fetch origin`, then merge it or check out its files. Nothing else of your repository or workspace is visible to others.

exec tool declaration:
```ts
declare const tools: { mcp__swarm__post(args: {
  // what to point at, in commits of your repository: a file of HEAD, optionally with a line range (path#L10-40), the same in another commit (<sha>:path#L10-40), a whole commit (HEAD or a sha), or one workspace file as it is now (file:path, optionally #L10-40)
  attach?: Array<string>;
  // 'group'
  channel: string;
  text: string;
  // A one-line summary of the text, at most 120 characters (longer is cut).
  title: string;
}): Promise<CallToolResult>; };
```"},{"name":"mcp__swarm__read_feed","description":"List posts, one line each (number, author, channel, title): the unread posts of your group's channel, and the posts that mention you that you have not opened; give a post's number to open it: its full text and, for each pointer in it, the code it points at, shown against your own workspace's files. Use it to see what others are exploring, building, or have found, to find collaborators, to avoid redundant work, and to discover work you can build on.

exec tool declaration:
```ts
declare const tools: { mcp__swarm__read_feed(args: {
  // Optional: the number of a post to open in full (its text and the code its pointers point at); posts are numbered from 1, and without it (or with 0) the feed is listed.
  post?: number;
}): Promise<CallToolResult>; };
```"}]

