def _name(fn, value):
    try: return fn(value).pw_name if fn is pwd.getpwuid else fn(value).gr_name
    except KeyError: return str(value)


def _fstype(path):
    """Return the type of the mounted filesystem containing path on Linux."""
    target = os.path.realpath(path)
    best = ('', '')
    try:
        with open('/proc/self/mountinfo', encoding='utf-8') as mounts:
            for line in mounts:
                fields = line.rstrip('\n').split(' ')
                sep = fields.index('-')
                mount = fields[4].replace('\\040', ' ').replace('\\011', '\t').replace('\\134', '\\')
                if (target == mount or target.startswith(mount.rstrip('/') + '/')) and len(mount) > len(best[0]):
                    best = (mount, fields[sep + 1])
    except (OSError, ValueError, IndexError):
        pass
    return best[1]


def _epoch_ns(ns):
    sec, frac = divmod(ns, 1_000_000_000)
    return '%d.%010d' % (sec, frac * 10)


def _date_ns(ns, style):
    try:
        sec, frac = divmod(ns, 1_000_000_000)
        d=datetime.datetime.fromtimestamp(sec).astimezone()
        if style == '+': return d.strftime('%Y-%m-%d+%H:%M:%S') + ('.%010d' % (frac * 10))
        if style == 'ctime': return d.strftime('%a %b %d %H:%M:%S.') + ('%010d' % (frac * 10)) + d.strftime(' %Y')
        if style == 'a': style = '%a %b %d %H:%M:%S %Y'
        elif style == 'b': style = '%b'
        elif style == 'c': style = '%a %b %e %H:%M:%S %Y'
        elif style == 'r': style = '%I:%M:%S %p'
        elif style == 'x': style = '%m/%d/%y'
        elif style == 'X': style = '%H:%M:%S'
        elif style == 'y': style = '%y'
        elif style == 'z': style = '%z'
        elif style == 'Z': style = '%Z'
        else: style = '%' + style
        return d.strftime(style)
    except (OverflowError, OSError, ValueError): return ''
"""Filesystem metadata predicates for find-compatible command line tools."""
import fnmatch
import grp
import os
import pwd
import re
import stat
import time
import datetime


def _cmp(value, spec):
    m = re.fullmatch(r'([+-]?)(\d+)', str(spec))
    if not m:
        return False
    op, n = m.group(1), int(m.group(2))
    return value > n if op == '+' else value < n if op == '-' else value == n


def _mode(spec, mode):
    """find -perm semantics: exact, all bits (-), or any bit (/)."""
    op = ''
    if spec.startswith(('-', '/', '+')):
        op, spec = spec[0], spec[1:]
    try:
        wanted = int(spec, 8)
    except ValueError:
        return False
    actual = stat.S_IMODE(mode)
    if op == '-':
        return actual & wanted == wanted
    if op == '/':
        return bool(actual & wanted)
    if op == '+':
        return bool(actual & wanted)
    return actual == wanted


def _size(spec, size):
    m = re.fullmatch(r'([+-]?)(\d+)([cwbkKMGTP]?)', str(spec))
    if not m:
        return False
    op, n, unit = m.groups()
    mult = {'': 512, 'b': 512, 'c': 1, 'w': 2, 'k': 1024, 'K': 1024,
            'M': 1024**2, 'G': 1024**3, 'T': 1024**4, 'P': 1024**5}[unit]
    # find rounds up to the selected unit before comparing.
    blocks = (size + mult - 1) // mult
    return _cmp(blocks, op + n)


def _type(st, wanted, follow=False, path=None):
    mode = st.st_mode
    if stat.S_ISLNK(mode) and follow:
        try:
            mode = os.stat(path).st_mode
        except OSError:
            return False
    ty = ('b' if stat.S_ISBLK(mode) else 'c' if stat.S_ISCHR(mode) else
          'd' if stat.S_ISDIR(mode) else 'p' if stat.S_ISFIFO(mode) else
          'f' if stat.S_ISREG(mode) else 'l' if stat.S_ISLNK(mode) else
          's' if stat.S_ISSOCK(mode) else '?')
    return ty in wanted


def evaluate(name, arg, path, st, depth=0, follow=False, now=None):
    """Evaluate a stat-based predicate. Return None for unsupported predicates."""
    name = name.lstrip('-')
    if name == 'depth':
        return _cmp(depth, arg)
    if name == 'type':
        return _type(st, arg, follow, path)
    if name == 'xtype':
        return _type(st, arg, not follow, path)
    if name == 'size':
        return _size(arg, st.st_size)
    if name == 'perm':
        return _mode(arg, st.st_mode)
    if name in ('uid', 'gid', 'inum', 'links'):
        value = {'uid': st.st_uid, 'gid': st.st_gid, 'inum': st.st_ino,
                 'links': st.st_nlink}[name]
        return _cmp(value, arg)
    if name in ('user', 'group'):
        value = st.st_uid if name == 'user' else st.st_gid
        try:
            target = int(arg)
        except ValueError:
            try:
                target = pwd.getpwnam(arg).pw_uid if name == 'user' else grp.getgrnam(arg).gr_gid
            except KeyError:
                return False
