def _cmp(value, spec):
    m = re.fullmatch(r'([+-]?)(\d+)', str(spec))
    if not m:
        return False
    op, n = m.group(1), int(m.group(2))
    return value > n if op == '+' else value < n if op == '-' else value == n


def _birthtime(path, st):
    """Return birth time where the OS exposes statx/struct stat birth time."""
    value = getattr(st, 'st_birthtime', None)
    if value is not None:
        return value
    try:
        libc = ctypes.CDLL(None, use_errno=True)
        statx = libc.statx
        statx.argtypes = (ctypes.c_int, ctypes.c_char_p, ctypes.c_int,
                          ctypes.c_uint, ctypes.c_void_p)
        statx.restype = ctypes.c_int
        buf = (ctypes.c_ubyte * 256)()
        if statx(-100, os.fsencode(path), 0, 0x800, buf) == 0:
            mask = struct.unpack_from('<I', buf, 0)[0]
            if mask & 0x800:
                sec, nsec = struct.unpack_from('<qI', buf, 80)
                return sec + nsec / 1_000_000_000
    except (AttributeError, OSError, ValueError, TypeError):
        pass
    return st.st_ctime


def _mode(spec, mode):
    """find -perm semantics: exact, all bits (-), or any bit (/)."""
    op = ''
